if (!msg.payload.item_code || !msg.payload.qty || !msg.payload.warehouse) {
    node.status({fill:"red", shape:"dot", text:"Missing fields"});
    return null;
}

const qty = parseFloat(msg.payload.qty);
if (isNaN(qty)) {
    node.status({fill:"red", shape:"dot", text:"Invalid qty"});
    return null;
}

msg.payload = {
    doctype: "Stock Entry",
    stock_entry_type: "Material Receipt",
    company: "My Company",
    items: [
        {
            item_code: msg.payload.item_code,
            qty: qty,
            warehouse: msg.payload.warehouse
        }
    ]
};

node.status({fill:"green", shape:"dot", text:"Ready"});
return msg;

if (msg.statusCode === 200 || msg.statusCode === 201) {
    node.status({fill:"green", shape:"dot", text:"Success"});
    msg.payload = {status: "success", message: "Stock Entry created"};
} else {
    node.status({fill:"red", shape:"dot", text:"Error: " + msg.statusCode});
    msg.payload = {status: "error", code: msg.statusCode, error: msg.payload};
}
return msg;
